-- Cron jobs send no Supabase API key or JWT (#397). Every Edge Function job
-- sends only Content-Type and x-cron-secret from Vault (track-shipments keeps
-- its own Bearer secret and is unchanged); the two workers read the new Vault
-- secrets checkout_recovery_worker_cron_secret and
-- reconcile_stripe_fees_cron_secret, and every URL comes from project_url.
-- Generated by `supabase db schema declarative sync`, then edited: the
-- generated cron.unschedule calls were removed, because
-- cron.schedule_in_database on an existing name updates the job in place and
-- keeps its jobid and run history.
SET local check_function_bodies = off;

SELECT cron.schedule_in_database('account-closure-cleanup', '0 * * * *', 'select net.http_post(
    url := (select decrypted_secret from vault.decrypted_secrets where name = ''project_url'') || ''/functions/v1/account-closure-cleanup'',
    headers := jsonb_build_object(
      ''Content-Type'', ''application/json'',
      ''x-cron-secret'', (select decrypted_secret from vault.decrypted_secrets where name = ''account_closure_cleanup_cron_secret'')
    ),
    body := ''{}''::jsonb
  )', 'postgres', NULL, true);

